<script setup lang="ts">
import { Check, FileArchive, Upload, X } from '@lucide/vue'
import StatusBadge from '@/components/common/StatusBadge.vue'
import MarketAssetField from './MarketAssetField.vue'
import type { CatalogResource, CatalogResourceKind, CatalogVersion } from '@/types/catalog-resources'
import type { DeliveryPolicy, MarketType } from '@/types/markets'

interface CatalogMeta { eyebrow: string; item: string }
interface BaseForm { id: string; name: string; description: string; category: string; tagsText: string; assetUrl: string; distributionType: 'public' | 'protected'; defaultDeliveryPolicy: DeliveryPolicy; marketTypes: MarketType[] }
interface VersionForm { version: string; releaseNotes: string; minDesktopVersion: string; configMode: 'form' | 'json'; transport: 'remote' | 'stdio'; url: string; command: string; packageName: string; argsText: string; envText: string; configText: string }
interface DistributionForm { enabled: boolean; selectedVersionId: string; deliveryPolicy: DeliveryPolicy; versionPolicy: 'manual' | 'follow_latest'; audienceType: 'all' | 'membership_cards'; membershipCardIds: string[] }

defineProps<{ open: boolean; kind: CatalogResourceKind; meta: CatalogMeta; editingId: string; saving: boolean; versionSaving: boolean; detail: CatalogResource | null; form: BaseForm; versionForm: VersionForm; distributionForm: DistributionForm; packageFile: File | null; errorMessage: string; canManage: boolean; canPublish: boolean; canDistribute: boolean }>()
const emit = defineEmits<{ close: []; saveBase: []; packageFile: [file: File | null]; saveVersion: []; publishVersion: [version: CatalogVersion]; saveDistribution: []; setStatus: [status: 'published' | 'disabled'] }>()

function selectFile(event: Event) {
  const file = (event.target as HTMLInputElement).files?.[0] || null
  emit('packageFile', file)
}

</script>

<template>
  <div v-if="open" class="drawer-backdrop-v2">
    <aside class="form-drawer-v2" role="dialog" aria-modal="true" :aria-label="editingId ? `管理${meta.item}` : `新建${meta.item}`">
      <header class="drawer-header"><div><span class="eyebrow">{{ meta.eyebrow }}</span><h2>{{ editingId ? `管理${meta.item}` : `新建${meta.item}` }}</h2></div><button class="icon-button" aria-label="关闭" :disabled="saving || versionSaving" @click="$emit('close')"><X :size="18" /></button></header>
      <div class="drawer-body">
        <section v-if="kind === 'mcp' && detail && canPublish && detail.sourceType !== 'official_sync'" class="form-section mcp-config-panel"><div class="section-heading"><span>配置</span><div><h3>MCP 连接配置</h3><p>可用表单快速配置，复杂场景切换到高级 JSON。</p></div></div><div class="segmented-control"><button type="button" :class="{ active: versionForm.configMode === 'form' }" @click="versionForm.configMode = 'form'">表单配置</button><button type="button" :class="{ active: versionForm.configMode === 'json' }" @click="versionForm.configMode = 'json'">高级 JSON</button></div><template v-if="versionForm.configMode === 'form'"><label><span>连接方式</span><select v-model="versionForm.transport"><option value="remote">远程 HTTPS</option><option value="stdio">本地 stdio</option></select></label><label v-if="versionForm.transport === 'remote'"><span>MCP 地址</span><input v-model.trim="versionForm.url" placeholder="https://example.com/mcp" /><small>客户端会自动完成 MCP 握手，无需填写 initialize 请求。</small></label><template v-else><div class="form-grid-v2"><label><span>运行命令</span><select v-model="versionForm.command"><option value="npx">npx</option><option value="uvx">uvx</option></select></label><label><span>固定版本包名</span><input v-model.trim="versionForm.packageName" placeholder="weather-mcp@1.0.0" /></label></div><label><span>参数（空格分隔）</span><input v-model="versionForm.argsText" placeholder="-y" /></label><label><span>环境变量（每行 KEY=VALUE）</span><textarea v-model="versionForm.envText" rows="3" placeholder="API_KEY=${API_KEY}" /></label></template></template><template v-else><label><span>MCP JSON 配置</span><textarea v-model="versionForm.configText" class="code-textarea" rows="10" /></label></template></section>
        <section v-if="detail && canPublish && detail.sourceType !== 'official_sync'" class="form-section"><div class="section-heading"><span>2</span><div><h3>发布状态</h3><p>停用后总后台目录和下游市场将不再提供此{{ meta.item }}。</p></div></div><label><span>状态</span><select :value="detail.status" :disabled="saving || versionSaving" @change="$emit('setStatus', ($event.target as HTMLSelectElement).value as 'published' | 'disabled')"><option value="published">已发布</option><option value="disabled">已停用</option></select></label></section>
        <section class="form-section"><div class="section-heading"><span>1</span><div><h3>基本信息</h3><p>用于个人市场列表和详情展示。</p></div></div><div class="form-grid-v2"><label><span>{{ meta.item }} ID</span><input v-model.trim="form.id" :disabled="Boolean(editingId)" :placeholder="kind === 'skill' ? 'data-analysis' : 'browser-tools'" /></label><label><span>分类</span><input v-model.trim="form.category" placeholder="例如 办公效率" /></label></div><label><span>名称</span><input v-model.trim="form.name" /></label><label><span>用途说明</span><textarea v-model.trim="form.description" rows="3" /></label><label><span>标签（逗号分隔）</span><input v-model="form.tagsText" /></label><MarketAssetField v-model="form.assetUrl" :label="kind === 'skill' ? '技能封面（可选）' : 'MCP 图标（可选）'" /><div v-if="kind === 'skill'" class="form-grid-v2"><label><span>分发类型</span><select v-model="form.distributionType" :disabled="Boolean(editingId && detail?.status !== 'draft')"><option value="public">公开技能</option><option value="protected">保护技能</option></select></label><label><span>默认交付</span><select v-model="form.defaultDeliveryPolicy"><option value="market">市场展示</option><option value="recommended">推荐更新</option><option value="auto_install">自动安装</option></select></label></div><div class="market-choice-grid compact-market-choices"><div class="selected"><strong>个人市场</strong><Check :size="17" /></div></div><button v-if="canManage && (!detail || detail.sourceType !== 'official_sync')" class="primary-button section-action" :disabled="saving" @click="$emit('saveBase')">{{ saving ? '保存中…' : editingId ? '保存基本信息' : `创建${meta.item}` }}</button></section>
        <section v-if="detail && canPublish && detail.sourceType !== 'official_sync'" class="form-section"><div class="section-heading"><span>2</span><div><h3>版本管理</h3><p>新版本先保存为草稿，再明确发布。</p></div></div><div class="form-grid-v2"><label><span>版本号</span><input v-model.trim="versionForm.version" placeholder="1.0.0" /></label><label><span>最低 Desktop 版本</span><input v-model.trim="versionForm.minDesktopVersion" placeholder="可选" /></label></div><label><span>更新说明</span><textarea v-model.trim="versionForm.releaseNotes" rows="3" /></label><label v-if="kind === 'skill'" class="file-drop"><FileArchive :size="23" /><span>{{ packageFile?.name || '选择技能 ZIP（最大 20 MB）' }}</span><input type="file" accept=".zip,application/zip" @change="selectFile" /></label><label v-else><span>MCP JSON 配置</span><textarea v-model="versionForm.configText" class="code-textarea" rows="10" /></label><button class="secondary-button section-action" :disabled="versionSaving" @click="$emit('saveVersion')"><Upload :size="16" />{{ versionSaving ? '保存中…' : '保存版本草稿' }}</button><div v-if="detail.versions?.length" class="version-list"><article v-for="version in detail.versions" :key="version.id"><div><strong>{{ version.version }}</strong><StatusBadge :status="version.status" /><p>{{ version.releaseNotes || '无更新说明' }}</p></div><button v-if="version.status !== 'published'" class="text-button" :disabled="versionSaving" @click="$emit('publishVersion', version)">发布版本</button></article></div></section>
        <section v-if="detail?.status === 'published' && canDistribute" class="form-section"><div class="section-heading"><span>3</span><div><h3>当前组织分发</h3><p>控制用户可见范围和版本跟随策略。</p></div></div><label class="switch-row"><span><strong>向当前组织用户上架</strong><small>关闭后客户端市场不再展示</small></span><input v-model="distributionForm.enabled" type="checkbox" /></label><div class="form-grid-v2"><label><span>分发版本</span><select v-model="distributionForm.selectedVersionId"><option value="">请选择已发布版本</option><option v-for="version in detail.versions?.filter((item) => item.status === 'published')" :key="version.id" :value="version.id">{{ version.version }}</option></select></label><label><span>版本策略</span><select v-model="distributionForm.versionPolicy"><option value="manual">手动确认</option><option value="follow_latest">自动跟随最新</option></select></label></div><label><span>交付策略</span><select v-model="distributionForm.deliveryPolicy"><option value="market">市场展示</option><option value="recommended">推荐更新</option><option value="auto_install">自动安装</option></select></label><button class="secondary-button section-action" :disabled="saving" @click="$emit('saveDistribution')">保存分发设置</button></section>
        <p v-if="errorMessage" class="drawer-error" role="alert">{{ errorMessage }}</p>
      </div>
      <footer class="drawer-footer"><button class="secondary-button" :disabled="saving || versionSaving" @click="$emit('close')">关闭</button></footer>
    </aside>
  </div>
</template>
